classify_section_1_tax_bracket_claim.procedure:
def apply(inputs, premises):
    income = float(inputs["taxable_income"])
    tier = len(inputs["bracket_rates"]) - 1
    found = False
    for i in range(len(inputs["finite_upper_bounds"])):
        if not found and income <= float(inputs["finite_upper_bounds"][i]):
            tier = i
            found = True
    lower_bound = 0.0
    if tier > 0:
        lower_bound = float(inputs["finite_upper_bounds"][tier - 1])
    calculated_tax = float(inputs["bracket_base_amounts"][tier]) + float(inputs["bracket_rates"][tier]) * (income - lower_bound)
    bracket_matches = int(inputs["cited_bracket_number"]) == tier + 1
    amount_matches = abs(float(inputs["claimed_tax_amount"]) - calculated_tax) <= 0.005
    if bracket_matches and amount_matches:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}

